# Seismic Rupture: "Seismic Rupture deals 2 damage to each creature without flying."
# ZNR Cinderclasm's "deals 2 damage to each creature" (DEAL_DAMAGE over ALL creatures) with M21
# Destructive Tampering's "creatures without flying" (FNot(KEYWORD_HAS FLYING)).
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=A(Verb.DEAL_DAMAGE, {
            'amount': QConst(value=2),
            'target': Selector(
                count=QUnbounded(),
                mode=SelectorMode.ALL,
                filter=FAnd(children=(
                    FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                    FNot(inner=FAtom(pred=FAtomPred.KEYWORD_HAS, keyword=Keyword.FLYING)),
                )),
                zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
            ),
        }),
    ),
]
